import com.nicolenkoe.hub.AppBuilds;import org.json.*;import com.sun.net.httpserver.*;import java.net.*;import java.nio.file.*;import java.nio.charset.*;
public class AllFreshBuildsTest{public static void main(String[]args)throws Exception{JSONObject fixtures=new JSONObject(new String(Files.readAllBytes(Paths.get("/workspace/work/build-fixtures.json")),"UTF-8")),sources=new JSONObject(AppBuilds.SOURCES);String[][] cases={{"CamaraD-downloads","0.25","25"},{"enduro-club-downloads","0.15.70","92"},{"fragment-logo-editor","1.3.7","15"},{"hvost-pod-kontrolem","0.64","64"},{"screen-recorder-downloads","0.1.1","0"},{"my-projects","1.17","18"}};int count=0;for(String[] c:cases){String name=c[0],source=sources.getString(name);Object fixture=fixtures.get(name);JSONObject expected=AppBuilds.select(fixture,source);JSONObject known=new JSONObject().put("version",c[1]).put("code",Integer.parseInt(c[2]));// Relative download URLs require the real source base. Add an absolute URL fixture for relative-format sources while preserving its format.
if(name.equals("CamaraD-downloads")){JSONArray r=((JSONObject)fixture).getJSONArray("releases");for(int i=0;i<r.length();i++){JSONObject row=r.getJSONObject(i),android=row.optJSONObject("android");if(android!=null)android.put("file",AppBuilds.safe(android.optString("file"),source));}}else if(name.equals("enduro-club-downloads")){JSONArray r=((JSONObject)fixture).getJSONArray("releases");for(int i=0;i<r.length();i++){JSONObject row=r.getJSONObject(i);row.put("apkUrl",AppBuilds.safe(row.optString("apkUrl"),source));}}
String body=name.equals("fragment-logo-editor")?"globalThis.FragmentCatalog="+fixture.toString()+";":fixture.toString();byte[] bytes=body.getBytes(StandardCharsets.UTF_8);HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/feed",ex->{if(ex.getRequestURI().getRawQuery()==null||!ex.getRequestHeaders().getFirst("Cache-Control").contains("no-cache")){ex.sendResponseHeaders(503,-1);ex.close();return;}ex.sendResponseHeaders(200,bytes.length);ex.getResponseBody().write(bytes);ex.close();});server.start();try{String testUrl="http://127.0.0.1:"+server.getAddress().getPort()+"/feed";
// Server bytes above intentionally use original payload; use a source-preserving local redirect-free selector for relative sources.
JSONObject fresh=AppBuilds.fetchLatest(name,testUrl,known);
if(fresh==null||!fresh.getString("version").equals(expected.getString("version"))||!fresh.getString("apk").equals(expected.getString("apk")))throw new AssertionError(name+" -> "+fresh);if(AppBuilds.compare(fresh,known)<=0)throw new AssertionError("Old version: "+name);System.out.println("PASS "+name+": "+known.getString("version")+" -> "+fresh.getString("version"));count++;}finally{server.stop(0);}}if(count!=6)throw new AssertionError();}}
